override fun visitElement(context: XmlContext, element: Element) {
    if (context.file.name != ANDROID_MANIFEST_XML) return
    when (element.tagName) {
        TAG_SERVICE -> { /* maybe no op, but we need know parent for meta-data */ }
        TAG_META_DATA -> {
            val parent = element.parentNode
            if (parent is Element && parent.tagName == TAG_SERVICE) {
                val name = element.getAttributeNS(ANDROID_URI, ATTR_NAME)
                val value = element.getAttributeNS(ANDROID_URI, ATTR_VALUE)
                if (name == WEARABLE_CONFIGURATION_ACTION && value == WATCH_FACE_EDITOR_VALUE) {
                    serviceMetas.add(context.getLocation(element))
                }
            }
        }
        TAG_ACTIVITY -> {
            activities.add(ActivityInfo(context.getLocation(element)))
        }
        TAG_ACTION -> {
            val actionName = element.getAttributeNS(ANDROID_URI, ATTR_NAME)
            if (actionName == ACTION_WATCH_FACE_EDITOR) {
                // find current activity
                val activity = findCurrentActivity(element)
                activity?.hasEditorAction = true
            }
        }
        TAG_CATEGORY -> {
            val catName = element.getAttributeNS(ANDROID_URI, ATTR_NAME)
            if (catName == CATEGORY_WEARABLE_CONFIGURATION) {
                val activity = findCurrentActivity(element)
                activity?.hasWearableConfigurationCategory = true
            }
        }
    }
}
```

